mapper.select:
SELECT * FROM inventory_outbound
WHERE deleted = 0

    AND outbound_type = #{outboundType}


    AND status = #{status}


    AND warehouse_id = #{warehouseId}


    AND (outbound_code LIKE CONCAT('%', #{keyword}, '%')
         OR reference_no LIKE CONCAT('%', #{keyword}, '%')
         OR target_name LIKE CONCAT('%', #{keyword}, '%'))


    AND outbound_date >= #{startDate}


    AND outbound_date <= #{endDate}

ORDER BY create_time DESC
